<?php
namespace App\Http\Controllers;
use App\Models\Applicant; use App\Models\ApplicantAttachment; use App\Services\EducationalWorkflowNotificationService; use App\Support\EmployeeScope; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str;
class ApplicantAttachmentController extends Controller {
 public function __construct(private readonly EducationalWorkflowNotificationService $notifications) {}
 private function access(Applicant $a): void { $user=request()->user(); abort_unless($user?->hasPermission('view_applicants'),403,'auth.forbidden'); if ($user->isSuperAdmin() || $user->hasPermission('view_all_applicants')) return; abort_unless(app(EmployeeScope::class)->canViewOwnedBy($user,$a->responsible_employee_id),403,'auth.forbidden'); }
 private function manage(Request $r, Applicant $a): void { $this->access($a); $user=$r->user(); abort_unless($user->hasPermission('edit_applicants'),403,'auth.forbidden'); if ($user->isSuperAdmin() || $user->hasPermission('view_all_applicants')) return; abort_unless(app(EmployeeScope::class)->canManageOwnedBy($user,$a->responsible_employee_id),403,'auth.forbidden'); }
 public function index(Applicant $applicant){ $this->access($applicant); return response()->json(['data'=>$applicant->attachments()->with('uploader:id,name')->latest()->get()->map(fn($a)=>$this->data($a))]); }
 public function store(Request $r, Applicant $applicant){ $this->manage($r,$applicant); $v=$r->validate(['file'=>['required','file','max:10240','mimes:pdf,txt,doc,docx,xls,xlsx,png,jpg,jpeg,webp'],'label'=>['required','string','max:120'],'category'=>['nullable','string','max:60']]); $f=$v['file']; $path=$f->storeAs("applicant-attachments/{$applicant->id}",Str::uuid().'.'.$f->extension(),'local'); $a=$applicant->attachments()->create(['uploaded_by'=>$r->user()->id,'label'=>$v['label'],'category'=>$v['category']??null,'disk'=>'local','path'=>$path,'original_name'=>$f->getClientOriginalName(),'mime_type'=>$f->getMimeType(),'size'=>$f->getSize()]); $this->notifications->applicantDocumentUploaded($applicant,$a,$r->user()->id); return response()->json(['data'=>$this->data($a)],201); }
 public function update(Request $r, Applicant $applicant, ApplicantAttachment $attachment){ $this->manage($r,$applicant); $this->owns($applicant,$attachment); $attachment->update($r->validate(['label'=>['required','string','max:120'],'category'=>['nullable','string','max:60']])); return response()->json(['data'=>$this->data($attachment)]); }
 public function download(Applicant $applicant, ApplicantAttachment $attachment){ $this->owns($applicant,$attachment); abort_unless(Storage::disk($attachment->disk)->exists($attachment->path),404); return Storage::disk($attachment->disk)->download($attachment->path,$attachment->original_name); }
 public function destroy(Request $r, Applicant $applicant, ApplicantAttachment $attachment){ $this->manage($r,$applicant); $this->owns($applicant,$attachment); Storage::disk($attachment->disk)->delete($attachment->path); $attachment->delete(); return response()->noContent(); }
 private function owns(Applicant $a, ApplicantAttachment $x): void { $this->access($a); abort_unless($x->applicant_id===$a->id,404); }
 private function data(ApplicantAttachment $a): array { return ['id'=>$a->id,'label'=>$a->label,'category'=>$a->category,'name'=>$a->original_name,'mime_type'=>$a->mime_type,'size'=>$a->size,'uploaded_at'=>$a->created_at?->toISOString(),'uploader'=>$a->uploader?->only(['id','name']),'download_url'=>"/api/applicants/{$a->applicant_id}/attachments/{$a->id}/download"]; }
}
